mapper.select:
SELECT m.id, m.warehouse_id AS warehouseId, w.name AS warehouseName, m.sku_id AS skuId, k.sku_code AS skuCode, k.spec_name AS skuName, m.lot_id AS lotId, t.lot_no AS lotNo, m.movement_type AS movementType, m.source_document_type AS sourceDocumentType, m.source_document_id AS sourceDocumentId, m.source_document_item_id AS sourceDocumentItemId, m.quantity, m.unit_snapshot AS unitSnapshot, m.before_quantity AS beforeQuantity, m.after_quantity AS afterQuantity, m.occurred_at AS occurredAt, m.operator FROM xsy_inventory_lot_movement m LEFT JOIN xsy_warehouse w ON w.id = m.warehouse_id LEFT JOIN xsy_product_sku k ON k.id = m.sku_id LEFT JOIN xsy_trace_lot t ON t.id = m.lot_id WHERE 1 = 1 AND FALSE
AND m.warehouse_id IN #{scopeId}
AND m.warehouse_id = #{query.warehouseId} AND m.sku_id = #{query.skuId}
AND t.lot_no ILIKE CONCAT('%', #{query.lotNo}, '%')
AND m.movement_type = #{query.movementType}
ORDER BY m.occurred_at DESC, m.id DESC
